-- Listing expansion, November 2026, batch 1: 14 new Chinese-speaking professional listings.
-- New rows only (on conflict (slug) do nothing). Category looked up by slug, so the same file runs on dev and production.

begin;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$joseph-lau-state-farm-chandler$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Joseph Lau, State Farm Agent$lx$, null, $lx$State Farm agent in Chandler offering auto, home, life and business insurance in English, Mandarin, Cantonese and Taiwanese.$lx$, $lx$錢德勒 State Farm 保險代理人，提供汽車、房屋、人壽及商業保險，可說英語、國語、粵語及台語。$lx$, $lx$Joseph Lau is a State Farm insurance agent with an office at 4080 W Ray Rd, Suite 20, in Chandler. His agency offers auto, motorcycle, homeowners, condo, renters, life and small business insurance, along with Medicare supplement and supplemental health plans, pet insurance, and U.S. Bank banking products offered through State Farm. The office serves customers in English, Mandarin, Cantonese and Taiwanese, and appointments are available on weekends and after hours.$lx$, $lx$Joseph Lau 是 State Farm 保險代理人，辦公室位於錢德勒（Chandler）4080 W Ray Rd, Suite 20。代理處提供汽車、機車、房屋、公寓、租屋、人壽及小型企業保險，也有聯邦醫療保險補充計畫（Medicare Supplement）、補充健康保險、寵物保險，以及透過 State Farm 合作提供的 U.S. Bank 銀行產品。辦公室可用英語、國語、粵語及台語服務，週末及下班後也可預約。$lx$, $lx$Chandler$lx$, $lx$Greater Phoenix$lx$, $lx$4080 W Ray Rd, Suite 20, Chandler, AZ 85226$lx$, null, $lx$(480) 759-0203$lx$, null, $lx$https://insurancewithjoseph.com/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$Taiwanese$lx$]::text[], array[$lx$Joseph Lau, State Farm Agent$lx$, $lx$Chandler$lx$, $lx$legal-finance$lx$, $lx$insurancewithjoseph.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$Taiwanese$lx$, $lx$insurance agent$lx$, $lx$保險$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$katie-lau-state-farm-mesa$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Katie Lau, State Farm Agent$lx$, null, $lx$Hong Kong-born State Farm agent in Mesa offering home, auto, business, life and health insurance in English, Cantonese and Mandarin.$lx$, $lx$在香港出生的梅薩 State Farm 保險代理人，提供房屋、汽車、商業、人壽及健康保險，可說英語、粵語及國語。$lx$, $lx$Katie Lau is a State Farm insurance agent with an office at 1245 W Guadalupe Rd, Suite B4, in Mesa. Born and raised in Hong Kong, she moved to the United States in 2003 and worked her way from bank teller to senior branch manager before becoming an agent; her site cites more than 22 years of experience in finance and insurance. Her agency handles home, auto, commercial, life and health insurance, and she offers service in English, Cantonese, Mandarin and Vietnamese. After-hours appointments are available.$lx$, $lx$Katie Lau 是 State Farm 保險代理人，辦公室位於梅薩（Mesa）1245 W Guadalupe Rd, Suite B4。她在香港出生長大，2003 年移民美國，從銀行櫃員一路做到資深分行經理，之後轉任保險代理人；她的網站表示她在金融與保險業已有超過 22 年經驗。代理處承辦房屋、汽車、商業、人壽及健康保險，可用英語、粵語、國語及越南語服務，下班後也可預約。$lx$, $lx$Mesa$lx$, $lx$Greater Phoenix$lx$, $lx$1245 W Guadalupe Rd, Suite B4, Mesa, AZ 85202$lx$, null, $lx$(602) 840-6655$lx$, null, $lx$https://katiemysfagent.com/$lx$, array[$lx$English$lx$, $lx$Cantonese$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Katie Lau, State Farm Agent$lx$, $lx$Mesa$lx$, $lx$legal-finance$lx$, $lx$katiemysfagent.com$lx$, $lx$English$lx$, $lx$Cantonese$lx$, $lx$Mandarin$lx$, $lx$insurance agent$lx$, $lx$保險$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

