values ($lx$lin-rawlinson-cpa-chandler$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Lin Rawlinson CPA, PC$lx$, null, $lx$Chandler CPA firm for business and personal taxes, bookkeeping and payroll, with Mandarin- and Cantonese-speaking staff.$lx$, $lx$錢德勒會計師事務所，承辦企業與個人報稅、記帳及薪資，團隊有會說國語及粵語的成員。$lx$, $lx$Lin Rawlinson CPA is a full-service accounting firm at 2450 S Arizona Ave in Chandler, led by Lin Chai Rawlinson, who has been a Certified Public Accountant in Arizona since 2003. The firm prepares business and personal tax returns and handles bookkeeping, payroll and payroll tax, sales tax filings, business licenses and new company formation for clients in Chandler, Gilbert, Tempe and nearby communities. Several team members are fluent in Mandarin and Cantonese, and the staff includes an IRS enrolled agent who can represent taxpayers before the IRS.$lx$, $lx$Lin Rawlinson CPA 是位於錢德勒 2450 S Arizona Ave 的全方位會計師事務所，負責人 Lin Chai Rawlinson 自 2003 年起為亞利桑那州執業會計師（CPA）。事務所承辦企業與個人報稅、記帳、薪資與薪資稅、營業稅申報、營業執照申請及新公司設立，服務錢德勒、吉爾伯特、坦佩及周邊地區的客戶。團隊中有多位成員能流利使用國語及粵語，另有一位可代表納稅人面對美國國稅局（IRS）的註冊稅務代理人（Enrolled Agent）。$lx$, $lx$Chandler$lx$, $lx$Greater Phoenix$lx$, $lx$2450 S Arizona Ave, Chandler, AZ 85286$lx$, null, $lx$(480) 570-7639$lx$, $lx$lin@lincpatax.com$lx$, $lx$https://www.lincpatax.com/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Lin Rawlinson CPA, PC$lx$, $lx$Chandler$lx$, $lx$legal-finance$lx$, $lx$lincpatax.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$CPA tax accountant$lx$, $lx$會計師 報稅$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$cpa-worldwide-tax-service-chandler$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$CPA Worldwide Tax Service PC$lx$, null, $lx$Chandler international tax CPA firm: ITIN applications, non-resident returns, FBAR and business taxes, in Chinese and English.$lx$, $lx$錢德勒國際稅務會計師事務所：ITIN 申請、非居民報稅、FBAR 及企業稅務，可用中文及英文服務。$lx$, $lx$CPA Worldwide Tax Service is an international tax CPA firm at 2045 N Dobson Rd, Suite 1, in Chandler. Its partner, Xieping "Oliver" Chen, is a licensed CPA in Arizona and an IRS enrolled agent who has worked on international tax and business issues for more than 16 years and works in both Chinese and English. Services include individual and business tax returns, ITIN applications as a Certified Acceptance Agent, non-resident tax returns, FBAR and foreign account reporting, foreign gifts and inheritances, foreign investment in U.S. real estate, business formation, and estate and trust tax work. The firm offers a free consultation.$lx$, $lx$CPA Worldwide Tax Service 是位於錢德勒 2045 N Dobson Rd, Suite 1 的國際稅務會計師事務所。合夥人 Xieping「Oliver」Chen 是亞利桑那州執業會計師（CPA）及美國國稅局註冊稅務代理人（EA），專精國際稅務與跨國商務問題超過 16 年，可用中文及英文服務。業務包括個人與企業報稅、以認證受理代理人（CAA）身分協助申請 ITIN、非居民報稅、FBAR 與海外帳戶申報、海外贈與及遺產、外國人投資美國房地產、公司設立，以及遺產與信託稅務。事務所提供免費諮詢。$lx$, $lx$Chandler$lx$, $lx$Greater Phoenix$lx$, $lx$2045 N Dobson Rd, Suite 1, Chandler, AZ 85224$lx$, null, $lx$(602) 515-6588$lx$, $lx$olivercpaea@gmail.com$lx$, $lx$https://www.cpaworldwidetax.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$CPA Worldwide Tax Service PC$lx$, $lx$Chandler$lx$, $lx$legal-finance$lx$, $lx$cpaworldwidetax.com$lx$, $lx$English$lx$, $lx$CPA tax accountant$lx$, $lx$會計師 報稅$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

