values ($lx$ling-zhu-phoenix$lx$, (select id from public.business_categories where slug = $lx$real-estate$lx$), $lx$Ling Zhu, RE/MAX Signature$lx$, null, $lx$Full-time RE/MAX Signature Realtor serving buyers and sellers across the Phoenix metro in English and Mandarin.$lx$, $lx$RE/MAX Signature 全職房地產經紀人，以英語及國語服務大鳳凰城地區的買家與賣家。$lx$, $lx$Ling Zhu is a full-time Realtor with RE/MAX Signature, whose office is at 19820 N 7th St, Suite 110, in Phoenix. She helps home buyers and sellers across the Phoenix metro area, lists Surprise, Gilbert, Peoria, Glendale and Chandler among her service areas, and speaks English and Mandarin. Her RE/MAX profile shows nine years of experience and specialties including first-time buyers, new construction, investment and retirement properties. Arizona license SA674361000.$lx$, $lx$Ling Zhu 是 RE/MAX Signature 的全職房地產經紀人，公司辦公室位於鳳凰城 19820 N 7th St, Suite 110。她協助大鳳凰城地區的買家與賣家，服務範圍包括 Surprise、吉爾伯特、皮奧里亞、格倫代爾及錢德勒，可說英語及國語。她的 RE/MAX 個人頁面顯示具九年經驗，專長包括首次購屋、新建案、投資及退休物業。亞利桑那執照號碼 SA674361000。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$19820 N 7th St, Suite 110, Phoenix, AZ 85024$lx$, $lx$Phoenix metro, including Surprise, Peoria, Glendale, Gilbert and Chandler$lx$, $lx$(602) 680-8132$lx$, null, $lx$https://www.remax.com/real-estate-agents/ling-zhu-phoenix-az/102100331$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Ling Zhu, RE/MAX Signature$lx$, $lx$Phoenix$lx$, $lx$real-estate$lx$, $lx$remax.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$realtor real estate agent$lx$, $lx$房地產經紀人 買房$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$christy-crouse-scottsdale$lx$, (select id from public.business_categories where slug = $lx$real-estate$lx$), $lx$Christy Crouse, RE/MAX Fine Properties$lx$, $lx$劉純$lx$, $lx$Mandarin-speaking RE/MAX Fine Properties associate serving Chinese-speaking buyers and sellers across the East Valley and Phoenix.$lx$, $lx$RE/MAX Fine Properties 會說國語的房地產經紀人，服務東谷及鳳凰城地區的華人買家與賣家。$lx$, $lx$Christy Crouse (劉純) is a Mandarin-speaking real estate associate with RE/MAX Fine Properties, whose office is at 21020 N Pima Rd in Scottsdale. A first-generation Chinese-American, she runs a Chinese-focused real estate website and works with buyers and sellers in Phoenix, Chandler, Gilbert, Mesa, Scottsdale and Tempe. Her site says she has sold hundreds of homes, and her RE/MAX profile lists 21 years of experience. Arizona license SA566516000.$lx$, $lx$劉純（Christy Crouse）是 RE/MAX Fine Properties 會說國語的房地產經紀人，公司辦公室位於斯科茨代爾 21020 N Pima Rd。她是第一代華裔美國人，經營以華人客戶為主的房地產網站，服務鳳凰城、錢德勒、吉爾伯特、梅薩、斯科茨代爾及坦佩的買家與賣家。她的網站表示她已售出數百棟房屋，RE/MAX 個人頁面顯示具 21 年經驗。亞利桑那執照號碼 SA566516000。$lx$, $lx$Scottsdale$lx$, $lx$Greater Phoenix$lx$, $lx$21020 N Pima Rd, Scottsdale, AZ 85255$lx$, $lx$Phoenix, Chandler, Gilbert, Mesa, Scottsdale and Tempe$lx$, $lx$(480) 332-5925$lx$, $lx$realtor.az@hotmail.com$lx$, $lx$https://phoenixchineserealestateagent.com/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Christy Crouse, RE/MAX Fine Properties$lx$, $lx$劉純$lx$, $lx$Scottsdale$lx$, $lx$real-estate$lx$, $lx$phoenixchineserealestateagent.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$realtor real estate agent$lx$, $lx$房地產經紀人 買房$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
