insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$jean-woodland-scottsdale$lx$, (select id from public.business_categories where slug = $lx$real-estate$lx$), $lx$Jean Woodland, Realty Executives Arizona Territory$lx$, null, $lx$North Scottsdale associate broker who helps clients buy, sell and invest in English, Mandarin and Cantonese.$lx$, $lx$北斯科茨代爾協理經紀人，以英語、國語及粵語協助客戶買房、賣房及投資。$lx$, $lx$Jean Woodland is an associate broker with Realty Executives Arizona Territory, working from its North Scottsdale office at 31307 N Scottsdale Rd. She speaks English, Mandarin and Cantonese and helps clients buy, sell and invest in real estate. Before real estate she spent years in admissions consulting and career counseling for international students, and more than a decade in international trade and business consulting, experience she now applies to negotiating for her clients.$lx$, $lx$Jean Woodland 是 Realty Executives Arizona Territory 的協理經紀人（Associate Broker），在公司位於 31307 N Scottsdale Rd 的北斯科茨代爾辦公室執業。她能說英語、國語及粵語，協助客戶買房、賣房及投資房地產。投身房地產前，她多年從事國際學生的升學顧問與職涯輔導，並有十多年國際貿易與商業顧問經驗，如今運用這些經驗為客戶談判。$lx$, $lx$Scottsdale$lx$, $lx$Greater Phoenix$lx$, $lx$31307 N Scottsdale Rd, Scottsdale, AZ 85266$lx$, null, $lx$(480) 679-9600$lx$, null, $lx$https://www.realtyexecutives.com/agents/jean-woodland$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Jean Woodland, Realty Executives Arizona Territory$lx$, $lx$Scottsdale$lx$, $lx$real-estate$lx$, $lx$realtyexecutives.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$Cantonese$lx$, $lx$realtor real estate agent$lx$, $lx$房地產經紀人 買房$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

