values ($lx$jane-zheng-merrill-phoenix$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Yijuan (Jane) Zheng, Merrill$lx$, null, $lx$Mandarin-speaking Merrill senior financial advisor in Phoenix focused on retirement, risk management and tax-aware planning.$lx$, $lx$鳳凰城會說國語的美林資深財務顧問，專注退休、風險管理及節稅規劃。$lx$, $lx$Yijuan (Jane) Zheng is a Senior Financial Advisor with Merrill at 2555 E Camelback Rd, Suite 900, in Phoenix. She has worked in financial services since 1994 and joined Merrill / Bank of America in 1997, holds the Chartered Retirement Planning Counselor designation, and earned a PhD in economics from the University of California, Santa Barbara. Her practice emphasizes risk management, capital preservation and tax sensitivity, and she works with clients' tax advisors and attorneys on income and estate taxes. She speaks fluent Chinese, including Mandarin.$lx$, $lx$Yijuan（Jane）Zheng 是美林（Merrill）資深財務顧問，辦公室位於鳳凰城 2555 E Camelback Rd, Suite 900。她自 1994 年起投入金融服務業，1997 年加入美林／美國銀行，持有退休規劃顧問（CRPC）認證，並擁有加州大學聖塔芭芭拉分校經濟學博士學位。她的服務著重風險管理、資本保全及節稅，並與客戶的稅務顧問及律師合作處理所得稅與遺產稅。她能說流利的中文，包括國語。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$2555 E Camelback Rd, Suite 900, Phoenix, AZ 85016$lx$, null, $lx$(602) 954-5049$lx$, null, $lx$https://advisor.ml.com/sites/az/phoenix-az/jane.zheng$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Yijuan (Jane) Zheng, Merrill$lx$, $lx$Phoenix$lx$, $lx$legal-finance$lx$, $lx$advisor.ml.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$financial advisor$lx$, $lx$財務顧問 理財$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$alexander-lu-merrill-scottsdale$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Alexander Lu, Merrill$lx$, null, $lx$Mandarin-speaking Merrill senior financial advisor in Scottsdale working with high-net-worth individuals and families.$lx$, $lx$斯科茨代爾會說國語的美林資深財務顧問，服務高資產個人與家庭。$lx$, $lx$Alexander Lu is a Senior Financial Advisor with Merrill Lynch Wealth Management in Scottsdale, at 14636 N Scottsdale Rd, and has been with Merrill since 2015. He works with high-net-worth individuals and families on asset allocation, education funding, retirement income planning, tax minimization strategies and estate planning, as part of a team with a combined 75 years in the industry. He earned an economics degree at the University of Michigan, holds FINRA Series 7 and 66 registrations, and is fluent in Mandarin.$lx$, $lx$Alexander Lu 是美林財富管理（Merrill Lynch Wealth Management）資深財務顧問，辦公室位於斯科茨代爾 14636 N Scottsdale Rd，自 2015 年起任職於美林。他為高資產個人與家庭規劃資產配置、教育基金、退休收入、節稅策略及遺產規劃，所屬團隊合計擁有 75 年業界經驗。他畢業於密西根大學經濟系，持有 FINRA Series 7 及 66 執照，能流利使用國語。$lx$, $lx$Scottsdale$lx$, $lx$Greater Phoenix$lx$, $lx$14636 N Scottsdale Rd, Scottsdale, AZ 85254$lx$, null, $lx$(480) 624-0434$lx$, null, $lx$https://advisor.ml.com/sites/az/scottsdale-az/alexander.lu$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Alexander Lu, Merrill$lx$, $lx$Scottsdale$lx$, $lx$legal-finance$lx$, $lx$advisor.ml.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$financial advisor$lx$, $lx$財務顧問 理財$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

