values ($lx$daisy-zhu-merrill-scottsdale$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Shiping (Daisy) Zhu, Merrill$lx$, null, $lx$Native Mandarin-speaking Merrill financial advisor and CFP professional in Scottsdale offering planning-based wealth management.$lx$, $lx$斯科茨代爾以國語為母語的美林財務顧問，持有 CFP 認證，提供以規劃為本的財富管理。$lx$, $lx$Shiping (Daisy) Zhu is a Financial Advisor with Merrill Lynch Wealth Management in Scottsdale, at 14636 N Scottsdale Rd, and a CERTIFIED FINANCIAL PLANNER professional. She takes a planning-based approach, helping individuals and families weigh investments, retirement planning, cash flow, education funding and other goals within their overall finances. Her Merrill profile lists Mandarin as her native language, and she also works in English.$lx$, $lx$Shiping（Daisy）Zhu 是美林財富管理（Merrill Lynch Wealth Management）財務顧問，辦公室位於斯科茨代爾 14636 N Scottsdale Rd，並持有 CFP 認證理財規劃師資格。她以規劃為本，協助個人與家庭在整體財務狀況下評估投資、退休規劃、現金流、教育基金及其他目標。她的美林個人頁面顯示國語為她的母語，她也能以英語服務。$lx$, $lx$Scottsdale$lx$, $lx$Greater Phoenix$lx$, $lx$14636 N Scottsdale Rd, Scottsdale, AZ 85254$lx$, null, $lx$(480) 607-8819$lx$, null, $lx$https://advisor.ml.com/sites/az/scottsdale-az/shiping.zhu$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Shiping (Daisy) Zhu, Merrill$lx$, $lx$Scottsdale$lx$, $lx$legal-finance$lx$, $lx$advisor.ml.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$financial advisor$lx$, $lx$財務顧問 理財$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$apex-dental-care-gilbert$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Apex Dental Care$lx$, null, $lx$Family dental practice in Gilbert since 1996, led by Dr. Wen H. Wang; service in English, Chinese and Spanish.$lx$, $lx$1996 年創立的吉爾伯特家庭牙科，由 Wen H. Wang 醫師主持，可用英語、中文及西班牙語服務。$lx$, $lx$Apex Dental Care is a family dental practice at 949 N Val Vista Dr, Suite 101, in Gilbert, founded in 1996 by Dr. Wen H. Wang, who has practiced general dentistry in Gilbert and the East Valley since 1995. The office offers cleanings and exams, white fillings, crowns and bridges, root canals, implant restorations, dentures, veneers and Zoom whitening, gum disease treatment, children's dentistry and emergency care, using digital X-rays. Service is available in English, Chinese and Spanish. Hours are Monday 7am-6pm, Tuesday 10am-6pm, Wednesday and Thursday 7am-5pm, and Friday 10am-1pm.$lx$, $lx$Apex Dental Care 是位於吉爾伯特（Gilbert）949 N Val Vista Dr, Suite 101 的家庭牙科診所，由 Wen H. Wang 醫師於 1996 年創立；他自 1995 年起在吉爾伯特及東谷地區執業一般牙科。診所提供洗牙與檢查、樹脂補牙、牙冠與牙橋、根管治療、植牙修復、假牙、貼片與 Zoom 美白、牙周病治療、兒童牙科及緊急處理，並使用數位 X 光。可用英語、中文及西班牙語服務。門診時間為週一上午 7 點至下午 6 點、週二上午 10 點至下午 6 點、週三及週四上午 7 點至下午 5 點、週五上午 10 點至下午 1 點。$lx$, $lx$Gilbert$lx$, $lx$Greater Phoenix$lx$, $lx$949 N Val Vista Dr, Suite 101, Gilbert, AZ 85234$lx$, null, $lx$(480) 813-8280$lx$, $lx$apexdentalcare@gmail.com$lx$, $lx$https://apexdentalcare.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$Apex Dental Care$lx$, $lx$Gilbert$lx$, $lx$medical$lx$, $lx$apexdentalcare.com$lx$, $lx$English$lx$, $lx$dentist$lx$, $lx$牙醫$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$joyce-h-huang-pllc-tempe$lx$, (select id from public.business_categories where slug = $lx$legal-finance$lx$), $lx$Joyce H. Huang, PLLC$lx$, null, $lx$Tempe immigration law firm with a Mandarin-speaking founding attorney: family petitions, work and investor visas, citizenship and court cases.$lx$, $lx$坦佩移民律師事務所，創辦律師會說國語：親屬移民、工作與投資簽證、入籍及移民法庭案件。$lx$, $lx$Joyce H. Huang, PLLC is a boutique immigration law firm at 1761 E McNair Dr, Suite 101, in Tempe. Founding attorney Joyce H. Huang is a member of the State Bar of Arizona and the American Immigration Lawyers Association and is fluent in English and Mandarin; the firm uses interpreters for Spanish, Vietnamese, Korean and other languages. It handles family petitions and adjustment of status, work and investor visas such as H-1B, L-1, E-2, EB-1, EB-2 NIW and EB-5, PERM labor certification, naturalization, waivers, asylum and removal defense. Consultations are free, and the office is open weekdays from 9am to 5:30pm.$lx$, $lx$Joyce H. Huang, PLLC 是位於坦佩（Tempe）1761 E McNair Dr, Suite 101 的精品移民律師事務所。創辦律師 Joyce H. Huang 為亞利桑那州律師公會及美國移民律師協會（AILA）會員，能流利使用英語及國語；事務所也為說西班牙語、越南語、韓語等語言的客戶安排口譯。業務涵蓋親屬移民與身分調整、H-1B、L-1、E-2、EB-1、EB-2 NIW 及 EB-5 等工作與投資簽證、PERM 勞工證、入籍、豁免申請、庇護及遞解出境辯護。提供免費諮詢，辦公時間為週一至週五上午 9 點至下午 5 點半。$lx$, $lx$Tempe$lx$, $lx$Greater Phoenix$lx$, $lx$1761 E McNair Dr, Suite 101, Tempe, AZ 85283$lx$, null, $lx$(480) 345-3323$lx$, $lx$info@joycehuangfirm.com$lx$, $lx$https://joycehuangfirm.com/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Joyce H. Huang, PLLC$lx$, $lx$Tempe$lx$, $lx$legal-finance$lx$, $lx$joycehuangfirm.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$immigration lawyer$lx$, $lx$移民律師$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

